package com.sliverzfx.gothicquest

/** Independently written reference notes; see docs/sources/remaining-game-tools-sources.md. */
internal object GothicRemakeToolsData {
    const val sourceNote = "Gothic 1 Remake • PC Console Tools mod 1.9.1 / equipment references"
    val codes = listOf(
        ToolReferenceEntry("g1r_setup", "CONSOLE TOOLS MOD", "Console setup and requirements", "PC only: install compatible UE4SS and alexz006’s G1R Console Tools mod using its installation guide. These commands require that mod; they are not the original Gothic Marvin console. Reference: Console Tools 1.9.1. Check the mod’s current compatibility and console key for your keyboard layout. Make a separate manual save before changing the world.", command = null, source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_help", "CONSOLE TOOLS MOD", "Command help", "Show the commands available in the installed mod.", command = "help", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_menu", "CONSOLE TOOLS MOD", "Item, skill and NPC browser", "Open the mod’s spawn browser. Use its lists to find identifiers supported by your installation.", command = "spawnmenu", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_additem", "CONSOLE TOOLS MOD", "Add items", "Give five copies of the documented sword example. General form: additem <ID> [count]; omitted count means one. Use items.txt from the mod for other IDs.", command = "additem ItMw_1H_Sword_01 5", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_removeitem", "CONSOLE TOOLS MOD", "Remove items", "Remove 100 gold. General form: removeitem <ID> [count]. Omitting the count removes every copy of that item.", command = "removeitem ItMi_Gold 100", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_skill", "CONSOLE TOOLS MOD", "Learn Acrobatics", "Learn the skill through the mod. Use skills.txt for other skill names. This bypasses normal training.", command = "addskill Acrobatics", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_unskill", "CONSOLE TOOLS MOD", "Remove Acrobatics", "Remove the learned skill. General form: removeskill <Skill>.", command = "removeskill Acrobatics", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_strength", "CONSOLE TOOLS MOD", "Set strength", "Set strength to 100, rather than adding 100. Other supported stat names: DEX, MP, HP, LP, LVL and XP.", command = "setstats STR 100", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_lp", "CONSOLE TOOLS MOD", "Set learning points", "Set the current learning-point amount to 50. This overwrites the current value.", command = "setstats LP 50", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_god", "CONSOLE TOOLS MOD", "God mode", "Keep health, mana, stamina and oxygen full. Use godmode off to disable; no argument toggles the mode.", command = "godmode on", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_mana", "CONSOLE TOOLS MOD", "Keep mana full", "Keep only mana full. The keepfull command also accepts health, oxygen and stamina, including several together. Use keepfull off to disable.", command = "keepfull mana on", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_immortal", "CONSOLE TOOLS MOD", "Survive lethal damage", "Lethal damage causes defeat instead of death; damage still reduces health. Use immortal off to disable.", command = "immortal on", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_parry", "CONSOLE TOOLS MOD", "Automatic parrying", "The mod raises the guard for incoming strikes. Use parrycheat off to disable.", command = "parrycheat on", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_onehit", "CONSOLE TOOLS MOD", "One-hit combat", "Reduce nearby NPC health to one. Use onehit off to restore affected health. Save before enabling around friendly NPCs.", command = "onehit on", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_hostiles", "CONSOLE TOOLS MOD", "Remove loaded hostile NPCs", "Kill loaded hostiles, optionally filtered by a name fragment: killenemy [name_part]. This changes the world; keep a separate save.", command = "killenemy", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_fly", "CONSOLE TOOLS MOD", "Fly mode", "Fly with WASD and camera direction at the supplied speed (default 1200). Caps Lock doubles speed. Disable with flymode off.", command = "flymode on 1200", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_flywalk", "CONSOLE TOOLS MOD", "Air walking", "Enable the mod’s air-walking mode; use flywalk off to stop. Flight modes share a slot and can temporarily suspend other cheats.", command = "flywalk on", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_sprint", "CONSOLE TOOLS MOD", "Double-Shift dash", "Configure a dash triggered by pressing Shift twice. Default strength is 600; disable with sprint off.", command = "sprint 600", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_jump", "CONSOLE TOOLS MOD", "Double-Space jump", "Configure the extra jump with multiplier 2. Trigger with a double Space press; disable with jump off.", command = "jump 2", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_position", "CONSOLE TOOLS MOD", "Read coordinates", "With no arguments, print your position. To move, supply three coordinates: teleport X Y Z.", command = "teleport", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_npcs", "CONSOLE TOOLS MOD", "Find NPC identifiers", "List matching NPC IDs. Without a filter, the list is limited to its first 50 entries. Runtime IDs can change.", command = "npclist Diego", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_goto", "CONSOLE TOOLS MOD", "Travel to an NPC", "Move to a matching NPC; an unloaded NPC may resolve to its starting position. Replace the example using npclist.", command = "gotonpc Diego", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_bring", "CONSOLE TOOLS MOD", "Bring a loaded NPC", "Move a matching loaded NPC to you. It cannot summon an unloaded NPC; check the current ID with npclist.", command = "bringnpc Diego", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_control", "CONSOLE TOOLS MOD", "Control the targeted NPC", "Toggle control of the NPC you are aiming at. Keep a save before experimenting with story characters.", command = "controlnpc", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_appearance", "CONSOLE TOOLS MOD", "Restore hero appearance", "Reset an appearance changed using becomenpc. That command is intended for human appearances, not creatures.", command = "becomenpc reset", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_doors", "CONSOLE TOOLS MOD", "Unlock nearby doors", "Unlock doors in the specified radius. Default radius is 1500. This can bypass story progression.", command = "unlocknearbydoors 1500", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_locks", "CONSOLE TOOLS MOD", "Unlock nearby mechanisms", "Unlock nearby chests, doors and levers in radius 1500. Save first; using a story mechanism early can break the intended order.", command = "unlocknearby 1500", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_time", "CONSOLE TOOLS MOD", "Read game time", "Display the current in-game date and time.", command = "getgametime", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_settime", "CONSOLE TOOLS MOD", "Set noon", "Set the time to 12:00:00. To set a day too, supply all four arguments: setgametime <day> <hours> <minutes> <seconds>.", command = "setgametime 12 0 0", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_skip", "CONSOLE TOOLS MOD", "Advance one hour", "Advance the game clock by 3600 seconds.", command = "skiptime 3600", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_freeze", "CONSOLE TOOLS MOD", "Freeze the clock", "Stop the game clock without freezing simulation. Resume with freezetime off.", command = "freezetime on", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_timescale", "CONSOLE TOOLS MOD", "Restore simulation speed", "Use multiplier 1 for normal simulation speed. Other multipliers change game speed.", command = "timescale 1", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_weather", "CONSOLE TOOLS MOD", "Set sunny weather", "Supported names include sunny, rain, rain2, rain3 and cloudy.", command = "setweather sunny", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_crimes", "CONSOLE TOOLS MOD", "Clear recorded crimes", "Clear crime records through the mod. This alters NPC-related state; make a manual save first.", command = "clearcrimes", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_quests", "CONSOLE TOOLS MOD", "Inspect active quests", "Read running quests. This is a lookup command; it does not alter quest progress.", command = "quests Running", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_questids", "CONSOLE TOOLS MOD", "Find quest identifiers", "List quests with details to look up current identifiers. Runtime quest IDs can change.", command = "quests None \"\" true", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_guild", "CONSOLE TOOLS MOD", "Inspect guild", "Display the current guild. Changing guild with guild set does not perform the story’s joining sequence.", command = "guild get", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_chapter", "CONSOLE TOOLS MOD", "Inspect chapter", "Display the current chapter. Forcing a number does not run story triggers.", command = "chapter", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_export", "CONSOLE TOOLS MOD", "Export character", "Write character data to character.txt in the mod folder. General form: exportchar [file]. Keep a normal game save as well.", command = "exportchar", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_import", "CONSOLE TOOLS MOD", "Import character", "Load character.txt from the mod folder. Inventory and skills are synchronized, so entries absent from the file are removed. Re-equip jewelry manually. Make a separate save first.", command = "importchar", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_hotkeys", "CONSOLE TOOLS MOD", "List configured hotkeys", "Inspect the mod’s configured hotkeys. Use its documentation for binding syntax and modifiers.", command = "hotkey list", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_barrier", "CONSOLE TOOLS MOD", "Barrier visual", "Disable the barrier glow. This command controls its visual effect.", command = "barrier off", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_retro", "CONSOLE TOOLS MOD", "Retro presentation", "Enable the mod’s retro effect; disable with retro off.", command = "retro on", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_hotbar", "CONSOLE TOOLS MOD", "Show hotbar", "Enable the mod’s hotbar display; disable with hotbar off.", command = "hotbar on", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_hpbar", "CONSOLE TOOLS MOD", "Show health bar", "Enable the mod’s health-bar display; disable with hpbar off.", command = "hpbar on", source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("g1r_quest_flags", "CONSOLE TOOLS MOD", "Quest flags are not a walkthrough", "setquest and forceqstate alter quest flags without executing the quest’s dialogue, rewards or triggers. They can leave the journal and world inconsistent. Keep an untouched save and use the quest guide to resolve the actual missing step.", command = null, source = "https://www.nexusmods.com/gothic1remake/mods/216?tab=docs", codeCategory = CodeCategory.GENERAL)
    ) + GothicRemakeItemData.entries
    val items = emptyList<ToolReferenceEntry>()
    val tips = listOf(
        ToolReferenceEntry("g1r_tip_equipment", "GAMEPLAY", "Compare equipment before buying", "Check damage, the required attribute and training before spending ore. A high-damage weapon is not an immediate upgrade if you cannot equip it. The equipment cards show known Remake values; missing values are left unspecified.", command = null, source = "https://www.gothic.tools/weapons", codeCategory = null),
        ToolReferenceEntry("g1r_tip_armor", "GAMEPLAY", "Read individual protection values", "Compare edge, blunt, point, fire and energy protection separately. The useful upgrade depends on what is hurting you. Check the armor cards before committing ore to a replacement.", command = null, source = "https://www.gothic.tools/armor", codeCategory = null),
        ToolReferenceEntry("g1r_tip_runes", "GAMEPLAY", "Budget mana and magic circles", "A rune can require a magic circle as well as mana. Check both before buying; possessing a rune alone does not grant its training.", command = null, source = "https://www.gothic.tools/items", codeCategory = null),
        ToolReferenceEntry("g1r_tip_lockpick", "GAMEPLAY", "Learn the Remake lock puzzle", "Lockpicking uses the Remake’s visible mechanism puzzle. Read the plates and feedback as you move through the lock; the original game’s memorized left/right sequences are not a solution here.", command = null, source = "https://www.gothic.tools/guides/lockpicking-and-chest-solutions", codeCategory = null),
        ToolReferenceEntry("g1r_tip_fingers", "GAMEPLAY", "Find lockpicking training", "Look for Fingers in the Old Camp near the arena area. Talk about training before tackling difficult locks, and keep spare lockpicks for mistakes.", command = null, source = "https://www.pcgamer.com/games/rpg/gothic-1-remake-how-to-lockpick-location/", codeCategory = null),
        ToolReferenceEntry("g1r_tip_ore", "GAMEPLAY", "Plan purchases around ore", "Compare listed item values before shopping. A reference value is not a guarantee of the price a trader will offer you; check the trade screen before accepting.", command = null, source = "https://www.gothic.tools/items", codeCategory = null),
        ToolReferenceEntry("g1r_tip_trainers", "GAMEPLAY", "Visit a trainer with a goal", "Choose the attribute or skill you need for your next upgrade, then find an appropriate trainer. Check the trainer’s actual offer and your available learning points before purchasing lessons.", command = null, source = "https://www.gothic.tools/trainers", codeCategory = null),
        ToolReferenceEntry("g1r_tip_trade", "GAMEPLAY", "Track traders by location", "Use the trader reference to plan shopping stops. Check each trader in the game for current stock rather than assuming every merchant sells the same supplies.", command = null, source = "https://www.gothic.tools/traders", codeCategory = null),
        ToolReferenceEntry("g1r_tip_recipes", "GAMEPLAY", "Keep ingredients until you check recipes", "Compare recipe requirements before selling crafting materials. Keep the ingredients for the recipe you intend to learn instead of clearing your bag solely by sale value.", command = null, source = "https://www.gothic.tools/recipes", codeCategory = null)
